-- ============================================================
-- AXL BOOKS — PRODUCTION CLEANUP + PRELOAD
-- Generated 2026-10-08T18:21:01.210Z from the Sep/Oct 2026 workbooks
-- + Data (1).xlsx (vehicle registry & dues accounts).
--
-- • Wipes ALL data tables (transactions, categories, vehicles,
--   payment_methods, dues_accounts, dues_checks).
-- • KEEPS auth.users, public.profiles (accounts) and app_settings.
-- • Re-seeds reference data + 262 transactions + 24 dues accounts.
-- • Wrap: runs in one transaction — all or nothing.
-- Run ONCE in Supabase SQL Editor.
-- ============================================================

begin;

-- ── 1. CLEANUP (data only — accounts untouched) ───────────────────────────
delete from public.dues_checks;
delete from public.dues_accounts;
delete from public.transactions;
delete from public.categories;
delete from public.vehicles;
delete from public.payment_methods;

-- app_settings kept (targets are config, not data). Optional reset:
-- update public.app_settings set monthly_income_target = 163350,
--   monthly_profit_target = 0, monthly_expense_target = 0, updated_at = now() where id = 1;

-- ── 2. Vehicle registry columns (idempotent guard) ────────────────────────
alter table public.vehicles
  add column if not exists tc_number text,
  add column if not exists owner_name text,
  add column if not exists license_expiry date,
  add column if not exists insurance_expiry date,
  add column if not exists salik_mobile text,
  add column if not exists salik_account text,
  add column if not exists salik_tag text,
  add column if not exists salik_code text;

-- ── 3. Reference data ─────────────────────────────────────────────────────



-- ── 4. Transactions (Sep + Oct 2026) ─────────────────────────────────────

-- ── 5. Dues & fines monitoring (24 accounts) ─────────────────────────────
create unique index if not exists dues_accounts_provider_label_uq
  on public.dues_accounts (provider_key, label);


-- ── 6. Verification ───────────────────────────────────────────────────────
select 'transactions' t, count(*) n, sum(amount) total from public.transactions
union all select 'income', count(*), sum(amount) from public.transactions where kind = 'income'
union all select 'expense', count(*), sum(amount) from public.transactions where kind = 'expense'
union all select 'categories', count(*), null from public.categories
union all select 'vehicles', count(*), null from public.vehicles
union all select 'payment_methods', count(*), null from public.payment_methods
union all select 'dues_accounts', count(*), null from public.dues_accounts;

commit;

